import asyncio
import logging
from collections.abc import AsyncIterator, Callable
from contextlib import AbstractAsyncContextManager
from typing import Annotated, Any, cast
from uuid import UUID, uuid4

from fastapi import Depends, FastAPI, Header, HTTPException
from fastapi.responses import JSONResponse, StreamingResponse
from opentelemetry import trace
from starlette.requests import Request

from crv_agent.api.dependencies import AppServices
from crv_agent.api.events import diagnostics, event
from crv_agent.api.identity import AuthenticationError
from crv_agent.api.schemas import ChatRequest, FeedbackRequest
from crv_agent.domain.answers import Answer
from crv_agent.domain.execution import Budget
from crv_agent.domain.planning import QueryPlan
from crv_agent.orchestration.context import ResearchContext
from crv_agent.ports.persistence import Run, Thread, ThreadNotFound, TurnConflict

logger = logging.getLogger(__name__)
# Custom graph stream events forwarded to clients; anything else stays server-side.
STREAMED_FINDINGS = frozenset({"facet"})


def leaf_types(error: BaseException) -> str:
    """Innermost exception class names (TaskGroup wraps failures in ExceptionGroups)."""
    if isinstance(error, BaseExceptionGroup):
        return ",".join(sorted({leaf_types(inner) for inner in error.exceptions}))
    return type(error).__name__


def create_app(
    services: AppServices | None = None,
    lifespan: Callable[[FastAPI], AbstractAsyncContextManager[None]] | None = None,
) -> FastAPI:
    app = FastAPI(title="CRV research backend", version="0.1.0", lifespan=lifespan)
    if services:
        app.state.services = services

    def dependencies() -> AppServices:
        value: AppServices = app.state.services
        return value

    async def owner(
        deps: Annotated[AppServices, Depends(dependencies)],
        authorization: Annotated[str | None, Header()] = None,
    ) -> str:
        try:
            return await deps.identity.owner(authorization)
        except AuthenticationError as error:
            raise HTTPException(401, "Authentication required") from error

    @app.exception_handler(ThreadNotFound)
    async def not_found(request: Request, error: ThreadNotFound) -> JSONResponse:
        return JSONResponse({"error": "not_found"}, status_code=404)

    @app.exception_handler(TurnConflict)
    async def conflict(request: Request, error: TurnConflict) -> JSONResponse:
        return JSONResponse({"error": "turn_conflict"}, status_code=409)

    @app.get("/health/live")
    async def live() -> dict[str, str]:
        return {"status": "alive", "mode": "development_only"}

    @app.get("/health/ready")
    async def ready(deps: Annotated[AppServices, Depends(dependencies)]) -> dict[str, str]:
        await deps.ready()
        return {"status": "ready", "authorization": "deferred"}

    @app.post("/api/v1/conversations")
    async def create(
        principal: Annotated[str, Depends(owner)],
        deps: Annotated[AppServices, Depends(dependencies)],
    ) -> Thread:
        return await deps.persistence.create_thread(principal, deps.search_release, deps.kg_release)

    @app.get("/api/v1/conversations")
    async def threads(
        principal: Annotated[str, Depends(owner)],
        deps: Annotated[AppServices, Depends(dependencies)],
    ) -> list[Thread]:
        return await deps.persistence.threads(principal)

    @app.get("/api/v1/conversations/{thread_id}")
    async def history(
        thread_id: UUID, principal: Annotated[str, Depends(owner)],
        deps: Annotated[AppServices, Depends(dependencies)],
    ) -> list[Run]:
        return await deps.persistence.history(principal, str(thread_id))

    @app.post("/api/v1/feedback", status_code=204)
    async def feedback(
        body: FeedbackRequest, principal: Annotated[str, Depends(owner)],
        deps: Annotated[AppServices, Depends(dependencies)],
    ) -> None:
        await deps.persistence.feedback(
            principal, str(body.thread_id), str(body.request_id), body.rating, body.comment,
        )

    @app.post("/api/v1/chat")
    async def chat(
        body: ChatRequest, request: Request, principal: Annotated[str, Depends(owner)],
        deps: Annotated[AppServices, Depends(dependencies)],
    ) -> StreamingResponse:
        thread_id, run_id = str(body.thread_id), str(body.request_id)
        thread = await deps.persistence.thread(principal, thread_id)
        if (thread.search_release, thread.kg_release) != (deps.search_release, deps.kg_release):
            raise HTTPException(409, "Thread release pins unavailable; create a new conversation")
        history = await deps.persistence.history(principal, thread_id)
        run, created = await deps.persistence.start_run(principal, thread_id, run_id, body.message)

        async def stream() -> AsyncIterator[str]:
            sequence = 0
            if not created:
                yield event("done", {
                    "status": run.status, "result": run.result, "replayed": True,
                }, sequence, run_id)
                return
            context = ResearchContext(
                models=deps.models, knowledge=deps.knowledge, worker=deps.worker,
                budget=Budget(
                    model_limit=deps.model_calls, token_limit=deps.turn_tokens,
                    seconds=deps.turn_seconds,
                ),
                search_release=thread.search_release, kg_release=thread.kg_release,
                trace_id=str(uuid4()), retrieval_mode=deps.retrieval_mode,
                facet_concurrency=deps.facet_concurrency, repair_mode=deps.repair_mode,
                diagnostics=deps.diagnostics, kg_results=deps.kg_results,
            )
            final: Answer | None = None
            persisted = False
            try:
                yield event("progress", {"step": "started"}, sequence, run_id)
                sequence += 1
                with trace.get_tracer("crv_agent").start_as_current_span("research_turn") as span:
                    span.set_attribute("crv.run_id", run_id)
                    span.set_attribute("crv.trace_id", context.trace_id)
                    span.set_attribute("crv.search_release", context.search_release)
                    span.set_attribute("crv.kg_release", context.kg_release)
                    async with asyncio.timeout(context.budget.seconds):
                        async for mode, streamed in deps.graph.astream(
                            {"question": body.message, "history": [
                                f"User: {previous.question}\nAssistant: "
                                f"{(previous.result or {}).get('content', '')}"
                                for previous in history[-7:] if previous.status == "completed"
                            ]},
                            {"configurable": {"thread_id": f"{thread_id}:{run_id}"}},
                            context=context, stream_mode=["updates", "custom"],
                        ):
                            if await request.is_disconnected():
                                raise asyncio.CancelledError
                            chunk = cast(dict[str, Any], streamed)
                            if mode == "custom":
                                if chunk.get("event") in STREAMED_FINDINGS or (deps.diagnostics and chunk.get("event") == "answer_diagnostics"):
                                    yield event(chunk["event"], {
                                        key: value for key, value in chunk.items()
                                        if key != "event"
                                    }, sequence, run_id)
                                    sequence += 1
                                continue
                            for step, values in chunk.items():
                                if step == "answer":
                                    final = Answer.model_validate(values["answer"])
                                yield event("progress", {"step": step}, sequence, run_id)
                                sequence += 1
                                if step == "understand":
                                    plan = QueryPlan.model_validate(values["plan"])
                                    yield event("plan", {
                                        "intent": plan.intent,
                                        "facets": [facet.question for facet in plan.facets],
                                    }, sequence, run_id)
                                    sequence += 1
                                if step == "research" and deps.diagnostics:
                                    yield event(
                                        "diagnostics", diagnostics(values or {}), sequence, run_id,
                                    )
                                    sequence += 1
                if final is None:
                    raise RuntimeError("Research graph produced no final answer")
                payload = final.model_dump(mode="json")
                await deps.persistence.finish_run(
                    principal, thread_id, run_id, "completed", payload,
                )
                persisted = True
                yield event("answer", payload, sequence, run_id)
                yield event("done", {"status": "completed"}, sequence + 1, run_id)
            except asyncio.CancelledError:
                if not persisted:
                    await asyncio.shield(deps.persistence.finish_run(
                        principal, thread_id, run_id, "cancelled", {"error": "cancelled"},
                    ))
                raise
            except Exception as error:
                logger.error(
                    "research_turn_failed run_id=%s error_type=%s",
                    run_id, leaf_types(error),
                )
                try:
                    await deps.persistence.finish_run(
                        principal, thread_id, run_id, "failed", {"error": type(error).__name__},
                    )
                except Exception as persistence_error:
                    logger.error(
                        "turn_failure_persistence_failed run_id=%s error_type=%s",
                        run_id, type(persistence_error).__name__,
                    )
                yield event("error", {
                    "error": "research_failed", "error_type": leaf_types(error),
                    "trace_id": context.trace_id,
                }, sequence, run_id)
        return StreamingResponse(
            stream(), media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    return app

orchestration__nodes__answer.py:
import json
import re

from langgraph.config import get_stream_writer
from langgraph.runtime import Runtime

from crv_agent.domain.answers import Answer, AnswerDraft, Conflict, Verdict
from crv_agent.domain.evidence import Calculation, Claim
from crv_agent.domain.execution import BudgetExceeded
from crv_agent.orchestration.context import ResearchContext
from crv_agent.orchestration.state import ResearchState
from crv_agent.services.verification import ungrounded_numbers, verify_draft


async def answer(
    state: ResearchState, runtime: Runtime[ResearchContext],
) -> dict[str, object]:
    context, plan = runtime.context, state["plan"]
    writer = get_stream_writer() if context.diagnostics else None

    def audit(stage: str, **payload: object) -> None:
        if writer is not None:
            writer({"event": "answer_diagnostics", "stage": stage, **payload})

    audit("input", claims=[claim.model_dump(mode="json") for claim in state["claims"]],
          coverage=state["coverage"].model_dump(),
          calculations=[item.model_dump(mode="json") for item in state["calculations"]])
    status = "answered"
    reasons: list[str] = []
    evidence = state["evidence"]
    claims = state["claims"]
    conflicts: list[Conflict] = []
    if plan.intent == "clarify":
        status, text = "needs_clarification", plan.clarification or (
            "Veuillez préciser le site, le document ou l'essai."
            if plan.language == "fr" else "Please specify the site, document or study."
        )
    elif plan.intent == "out_of_scope":
        status, text = "out_of_scope", (
            "Cette information ne peut pas être établie à partir du corpus documentaire disponible."
            if plan.language == "fr" else
            "This information cannot be established from the available document corpus."
        )
    elif plan.intent == "procedure":
        status, text = "out_of_scope", (
            "Cette demande dépasse ce backend de recherche documentaire. "
            "Les protocoles dangereux ne sont jamais synthétisés."
            if plan.language == "fr" else
            "This request is outside this research backend. "
            "Hazardous protocols are never synthesized."
        )
    elif not claims:
        status, text = "insufficient_evidence", (
            "Les éléments retrouvés ne permettent pas de répondre de façon étayée."
            if plan.language == "fr" else
            "The retrieved evidence is insufficient to support an answer."
        )
    else:
        details = json.dumps({
            "coverage": state["coverage"].model_dump(),
            "conflicts": [c.model_dump() for c in state["conflicts"]],
            "calculations": [c.model_dump(mode="json") for c in state["calculations"]],
            "premises_to_verify": plan.premises,
        }, ensure_ascii=False)
        draft: AnswerDraft | None = None
        verdict: Verdict | None = None
        pruned = listed = False
        try:
            for round_number in range(2):
                composed = await context.models.compose(
                    state["question"], claims, details + "\n" + "\n".join(reasons),
                    context.budget,
                )
                checked = verify_draft(
                    composed, evidence, context.search_release, state["calculations"],
                )
                used = {cid for claim in composed.claims for cid in claim.evidence_ids}
                judged = await context.models.verify(
                    composed, [item for item in evidence if item.id in used], details,
                    context.budget,
                )
                audit(
                    "verified", round=round_number + 1,
                    draft=composed.model_dump(mode="json"),
                    verifier=judged.model_dump(mode="json"), deterministic_errors=checked,
                )
                # Draft, verdict and reasons only change together, so a budget stop below
                # never pairs a new draft with the previous round's verdict.
                draft, verdict = composed, judged
                reasons = checked + (judged.reasons if not judged.supported else [])
                if not reasons:
                    break
                if context.repair_mode == "prune" and round_number == 0:
                    candidate = prune_ungrounded(draft, verdict, state["calculations"])
                    if candidate is not None and not verify_draft(
                        candidate, evidence, context.search_release, state["calculations"],
                    ):
                        draft, reasons, pruned = candidate, [], True
                        audit("pruned", round=round_number + 1,
                            draft=candidate.model_dump(mode="json"))
                        break
                # Converge on the single repair: drop exactly the claims the verifier rejected,
                # rather than asking the composer to rewrite a mis-bound claim it cannot edit.
                rejected = [
                    draft.claims[n] for n in verdict.unsupported_claims
                    if 0 <= n < len(draft.claims)
                ]
                claims = [claim for claim in claims if claim not in rejected]
                if not claims:
                    break
        except BudgetExceeded:
            if draft is None:
                reasons = ["The turn budget ran out before an answer could be verified."]
        if reasons and draft is not None and verdict is not None:
            candidate = prune_ungrounded(draft, verdict, state["calculations"])
            if candidate is not None and not verify_draft(
                candidate, evidence, context.search_release, state["calculations"],
            ):
                draft, reasons, pruned = candidate, [], True
                audit("pruned", round="final", draft=candidate.model_dump(mode="json"))
            elif (
                candidate := findings(draft, verdict, state["calculations"], plan.language)
            ) is not None and not verify_draft(
                candidate, evidence, context.search_release, state["calculations"],
            ):
                draft, reasons, listed = candidate, [], True
                audit("findings", draft=candidate.model_dump(mode="json"))
        if reasons or draft is None:
            status, text, claims = "insufficient_evidence", (
                "La réponse n'a pas passé la vérification des sources."
                if plan.language == "fr" else "The answer did not pass source verification."
            ), []
        else:
            text, claims = draft.content, draft.claims
            conflicts = answer_conflicts(draft, state["claims"], state["conflicts"])
            # Removed claims are listed in reasons; only unanswered or cut-short work is partial.
            status = "insufficient_evidence" if draft.insufficient else (
                "partial" if draft.unanswered or state["coverage"].incomplete or listed
                else "answered"
            )
            if pruned:
                reasons = ["Statements the verifier found unsupported were removed."]
            if listed:
                reasons = ["The synthesis failed verification; only verified findings are listed."]
            label = "Non couvert : " if plan.language == "fr" else "Not answered: "
            reasons += [label + part for part in draft.unanswered]
    selected = {cid for claim in claims for cid in claim.evidence_ids}
    result = Answer.model_validate({
        "status": status, "content": text,
        "claims": claims if selected else [],
        "citations": [item for item in evidence if item.id in selected],
        "conflicts": conflicts, "calculations": state["calculations"],
        "coverage": state["coverage"], "reasons": reasons,
        "search_release": context.search_release, "kg_release": context.kg_release,
        "trace_id": context.trace_id, "usage": context.budget.usage(),
        "role_usage": context.budget.role_usage(),
        "retrieval_mode": context.retrieval_mode,
    })
    audit("final", answer=result.model_dump(mode="json"))
    return {"answer": result}


_MARKER = re.compile(r"\[([^\[\]]+)\]")
_TRAILING_MARKERS = r"(?:[ \t]*\[[^\[\]\n]+\])*"
_CITATIONS_ONLY = re.compile(r"[\s.,;:-]*(?:\[[^\[\]\n]+\][\s.,;:-]*)+")
_EMPTY_ITEM = re.compile(r"\s*(?:[-*+]|\d+[.)])\s*")
_HEADING = re.compile(r"(#{1,6})\s+\S.*|\*\*[^*\n]+\*\*\s*[:.]?")


def heading_level(line: str) -> int | None:
    """Markdown heading depth; a bold-only line is the deepest level (7)."""
    match = _HEADING.fullmatch(line.strip())
    if match is None:
        return None
    return len(match.group(1)) if match.group(1) else 7


def tidy(content: str) -> str:
    """Drop citation-only lines, empty list items and headings that pruning left bodiless."""
    lines = [
        line for line in content.split("\n")
        if not _CITATIONS_ONLY.fullmatch(line) and not _EMPTY_ITEM.fullmatch(line)
    ]
    while True:
        kept = []
        for n, line in enumerate(lines):
            level = heading_level(line)
            following = next((later for later in lines[n + 1:] if later.strip()), None)
            if level is not None and (
                following is None
                or ((deeper := heading_level(following)) is not None and deeper <= level)
            ):
                continue
            kept.append(line)
        if kept == lines:
            break
        lines = kept
    return re.sub(r"[ \t]+\n", "\n", re.sub(r"\n{3,}", "\n\n", "\n".join(lines))).strip()


def prune_ungrounded(
    draft: AnswerDraft, verdict: Verdict, calculations: list[Calculation],
) -> AnswerDraft | None:
    """Prune verifier-rejected content plus sentences carrying numbers no claim grounds."""
    loose = ungrounded_numbers(draft.content, draft.claims, calculations)
    return prune(draft, verdict.model_copy(update={"unsupported_sentences": [
        *verdict.unsupported_sentences,
        *(s for s in sentences(draft.content) if any(n in s for n in loose)),
    ]}))


def prune(draft: AnswerDraft, verdict: Verdict) -> AnswerDraft | None:
    """Remove verbatim unsupported sentences and rejected claims; None if nothing remains.

    Only deletes text, so it cannot introduce unsupported content; the caller re-runs the
    deterministic citation contract on the result.
    """
    if not verdict.unsupported_sentences and not verdict.unsupported_claims:
        return None
    content = draft.content
    for sentence in verdict.unsupported_sentences:
        if sentence.strip() and sentence.strip() in content:
            content = re.sub(re.escape(sentence.strip()) + _TRAILING_MARKERS, "", content)
    content = tidy(content)
    rejected = {n for n in verdict.unsupported_claims if 0 <= n < len(draft.claims)}
    while True:
        markers = set(re.findall(r"\[([^\[\]]+)\]", content))
        claims = [
            claim for n, claim in enumerate(draft.claims)
            if n not in rejected and set(claim.evidence_ids) <= markers
        ]
        bound = {cid for claim in claims for cid in claim.evidence_ids}
        orphans = [s for s in sentences(content) if set(_MARKER.findall(s)) - bound]
        if not orphans:
            break
        for sentence in orphans:
            content = content.replace(sentence, "")
        content = tidy(content)
    if not content or not claims or content == draft.content.strip():
        return None
    kept = {id(claim): n for n, claim in enumerate(claims)}
    conflicts = [
        conflict.model_copy(update={"claim_indices": indices})
        for conflict in draft.conflicts
        if len(indices := sorted(
            kept[id(draft.claims[i])] for i in conflict.claim_indices
            if id(draft.claims[i]) in kept
        )) >= 2
    ]
    return draft.model_copy(update={"content": content, "claims": claims, "conflicts": conflicts})


def findings(
    draft: AnswerDraft, verdict: Verdict, calculations: list[Calculation], language: str,
) -> AnswerDraft | None:
    """Unrejected, self-grounded claims listed with citations; None for a blanket rejection."""
    if not verdict.unsupported_claims and not verdict.unsupported_sentences:
        return None
    rejected = set(verdict.unsupported_claims)
    lines: list[str] = []
    claims: list[Claim] = []
    for n, claim in enumerate(draft.claims):
        line = f"- {claim.text} " + " ".join(f"[{cid}]" for cid in claim.evidence_ids)
        if n in rejected or _MARKER.search(claim.text) or ungrounded_numbers(
            line, [claim], calculations,
        ):
            continue
        lines.append(line)
        claims.append(claim)
    if not claims:
        return None
    intro = (
        "La synthèse n'a pas passé la vérification des sources ; seuls les constats "
        "vérifiés sont listés." if language == "fr" else
        "The synthesis did not pass source verification; only verified findings are listed."
    )
    return AnswerDraft(
        content=intro + "\n\n" + "\n".join(lines), claims=claims,
        insufficient=draft.insufficient,
    )


def answer_conflicts(
    draft: AnswerDraft, ledger: list[Claim], detected: list[Conflict],
) -> list[Conflict]:
    """Composer-identified conflicts plus deterministic ones, indexed into the answer claims."""
    position = {claim.model_dump_json(): n for n, claim in enumerate(draft.claims)}
    result = list(draft.conflicts)
    for conflict in detected:
        indices = sorted({
            position[key] for i in conflict.claim_indices
            if 0 <= i < len(ledger) and (key := ledger[i].model_dump_json()) in position
        })
        if len(indices) >= 2 and all(set(indices) != set(c.claim_indices) for c in result):
            result.append(conflict.model_copy(update={"claim_indices": indices}))
    return result


def sentences(content: str) -> list[str]:
    """Sentence or list-item units of the answer, for verbatim pruning."""
    return [
        part.strip() for part in re.split(r"(?<=[.!?])\s+|\n+", content) if part.strip()
    ]

orchestration__nodes__research.py:
import asyncio
import json
import logging

from langgraph.runtime import Runtime

from crv_agent.domain.answers import Coverage
from crv_agent.domain.evidence import (
    Calculation,
    CalculationRequest,
    Claim,
    Evidence,
    TracedWorkerResult,
    WorkerResult,
)
from crv_agent.domain.execution import BudgetExceeded
from crv_agent.domain.planning import Document, Facet, QueryPlan
from crv_agent.orchestration.context import ResearchContext
from crv_agent.orchestration.state import ResearchState
from crv_agent.services.anchoring import anchor_claim
from crv_agent.services.calculation import calculate
from crv_agent.services.catalogue import enumerate_documents
from crv_agent.services.evidence_pack import merge_exposure
from crv_agent.services.kg_guidance import KG_INTENTS, kg_documents
from crv_agent.services.navigation import steering_entities
from crv_agent.services.policy import hazardous_instructions
from crv_agent.services.reconciliation import conflicts
from crv_agent.services.verification import claim_errors

logger = logging.getLogger(__name__)


async def understand(
    state: ResearchState, runtime: Runtime[ResearchContext],
) -> dict[str, object]:
    context = runtime.context
    if hazardous_instructions(state["question"]):
        plan = QueryPlan(
            intent="procedure", language="en"
            if state["question"].lower().startswith(("how ", "what ", "which ")) else "fr",
            facets=[], identifiers=[], premises=[],
            clarification=None,
        )
    else:
        plan = await context.models.plan(state["question"], state["history"], context.budget)
    return {
        "plan": plan, "claims": [], "evidence": [], "calculations": [], "conflicts": [],
        "coverage": Coverage(),
    }


async def research(
    state: ResearchState, runtime: Runtime[ResearchContext],
) -> dict[str, object]:
    context, plan = runtime.context, state["plan"]
    if plan.intent in {"clarify", "out_of_scope", "procedure"}:
        return {}
    entities = []
    if context.retrieval_mode == "kg":
        await context.budget.reserve(retrieval=1)
        entities = await context.budget.wait(
            context.knowledge.resolve(state["question"], context.kg_release),
        )
    gaps = [f"Candidate entity mapping: {e.name}" for e in entities if e.status == "candidate"]
    coverage = Coverage(gaps=gaps)
    hashes: list[str] = []
    docs: list[Document] = []
    if context.retrieval_mode == "search":
        gaps.append("Search-only baseline; no KG catalogue enumeration or navigation.")
    navigation = steering_entities(entities, plan.intent)
    if context.retrieval_mode == "kg" and (plan.intent == "catalogue" or navigation):
        try:
            docs, coverage = await enumerate_documents(
                context.knowledge, [e.iri for e in navigation], context.kg_release, context.budget,
            )
        except BudgetExceeded:
            return {"coverage": Coverage(gaps=["Catalogue enumeration exceeded the turn budget."])}
        hashes = list(dict.fromkeys(doc.content_hash for doc in docs if doc.content_hash))
        gaps.extend(coverage.gaps)
        if any(not doc.content_hash for doc in docs):
            gaps.append("Some KG documents have no Search-compatible content hash.")
    if plan.intent == "catalogue":
        items = []
        for doc in docs:
            await context.budget.reserve(retrieval=1)
            lineage = await context.budget.wait(
                context.knowledge.lineage(doc.iri, context.kg_release),
            )
            items.append({"document": doc.model_dump(mode="json"), "lineage": lineage})
            if len(items) == 12 and len(docs) > 12:
                gaps.append("Catalogue details limited to 12 documents; narrow the request.")
                coverage = coverage.model_copy(update={"incomplete": True})
                break
        # Catalogue observations retain an explicit filename/manifest basis, not scientific facts.
        evidence = [
            Evidence(
                id=f"catalogue:{i}", release=context.search_release, chunk_id="",
                content_hash=doc.content_hash or "", title=doc.title,
                content=json.dumps(items[i], ensure_ascii=False), source_uri=doc.source_paths[0]
                if doc.source_paths else doc.iri, pages=[],
                locators=[f"catalogue:{doc.iri}"], original_sources=doc.source_paths,
                generated=False, document_class="catalogue_metadata",
            ) for i, doc in enumerate(docs[:len(items)])
        ]
        catalogue_claims = [
            Claim(
                text=f"Catalogue metadata (filename/manifest basis): {item.title}",
                evidence_ids=[item.id], quote=item.content, subject=item.title,
                quantity=None, value=None, unit=None, date=None, conditions=None, scope=None,
            ) for item in evidence
        ]
        return {
            "evidence": evidence, "claims": catalogue_claims,
            "coverage": coverage.model_copy(update={"visited": len(items), "gaps": gaps}),
        }
    # (facet, documents, strict): a strict facet searches only its documents.
    runs = [(facet, hashes, False) for facet in plan.facets or [Facet(question=state["question"])]]
    if (
        context.kg_results and context.retrieval_mode == "kg" and navigation
        and plan.intent in KG_INTENTS
    ):
        try:
            await context.budget.reserve(retrieval=1)
            studies = await context.budget.wait(context.knowledge.studies(
                [e.iri for e in navigation], context.kg_release,
            ))
        except BudgetExceeded:
            studies = []
        if chosen := kg_documents(studies):
            # First, so a large plan cannot exhaust the turn budget before it searches.
            runs.insert(0, (Facet(question=state["question"]), chosen, True))
            gaps.append("KG-2 studies chose the documents of one search; cited text only.")
    gaps.append("Top-k evidence retrieval is not an exhaustive corpus review.")
    semaphore = asyncio.Semaphore(context.facet_concurrency)
    evidence_by_id: dict[str, Evidence] = {}
    claims: dict[str, Claim] = {}
    audit: list[dict[str, object]] = []

    async def run(facet: Facet, scope: list[str], strict: bool) -> None:
        accepted: list[Claim] = []
        status = "completed"
        result: WorkerResult | None = None
        async with semaphore:
            try:
                result, found = await context.worker.run(
                    facet.question + "\nOriginal question: " + state["question"]
                    + "\nPremises to verify: " + "; ".join(plan.premises),
                    context.search_release, scope, context.budget, strict=strict,
                )
                for item in found:
                    previous = evidence_by_id.get(item.id)
                    evidence_by_id[item.id] = (
                        item if previous is None else merge_exposure(previous, item)
                    )
                gaps.extend(result.gaps)
                for claim in (anchor_claim(raw, found) for raw in result.claims):
                    errors = claim_errors(claim, evidence_by_id)
                    if not errors:
                        claims[claim.model_dump_json()] = claim
                        accepted.append(claim)
                    else:
                        logger.warning("worker_claim_rejected errors=%s", "; ".join(errors))
                        gaps.append("A worker claim failed source/locator/value validation.")
            except BudgetExceeded:
                status = "budget_exhausted"
                gaps.append("A research facet exhausted the shared execution budget.")
            except Exception as error:
                status = "failed"
                failures.append(error)
                logger.warning("research_facet_failed error_type=%s", type(error).__name__)
                gaps.append(
                    f"A research facet failed ({type(error).__name__}); its evidence is missing.",
                )
        if context.diagnostics:
            audit.append(facet_audit(facet.question, status, result, evidence_by_id))
            audit[-1].update({"scope_hashes": scope, "strict": strict})
        if status != "completed":
            cut_short.append(facet.question)
        # Early findings, not a verified answer: every streamed claim's quote is located verbatim.
        cited = {cid for claim in accepted for cid in claim.evidence_ids}
        runtime.stream_writer({
            "event": "facet", "facet": facet.question, "status": status,
            "claims": [claim.model_dump(mode="json") for claim in accepted],
            "sources": [
                {
                    "id": item.id, "title": item.title,
                    "source": item.source_path or item.source_uri, "pages": item.pages,
                    "document_code": item.document_code, "source_role": item.source_role,
                } for item in sorted(evidence_by_id.values(), key=lambda e: e.id)
                if item.id in cited
            ],
        })
    failures: list[Exception] = []
    cut_short: list[str] = []
    async with asyncio.TaskGroup() as group:
        for facet, scope, strict in runs:
            group.create_task(run(facet, scope, strict))
    if failures and len(failures) == len(runs):
        # Every facet failed: a provider/tool failure, never an absence-of-evidence answer.
        raise failures[0]
    visited = len({e.content_hash for e in evidence_by_id.values()})
    if coverage.matched > visited:
        gaps.append("Evidence retrieval did not inspect every enumerated document.")
    return {
        "evidence": sorted(evidence_by_id.values(), key=lambda e: e.id),
        "claims": [claims[key] for key in sorted(claims)],
        "coverage": coverage.model_copy(update={
            "visited": visited, "gaps": sorted(set(gaps)),
            "incomplete": coverage.incomplete or bool(cut_short),
        }),
        **({"audit": audit} if context.diagnostics else {}),
    }


def facet_audit(
    facet: str, status: str, result: WorkerResult | None, evidence: dict[str, Evidence],
) -> dict[str, object]:
    """Every claim a facet's worker returned, with its outcome and validation errors."""
    rounds = result.rounds if isinstance(result, TracedWorkerResult) else []
    seen = {pid for extraction in rounds for pid in extraction.passage_ids}
    shown = [item for pid, item in evidence.items() if pid in seen or not rounds]
    returned = [
        (n, claim, "capped" if capped else "") for n, extraction in enumerate(rounds)
        for capped, group in ((False, extraction.returned), (True, extraction.capped))
        for claim in group
    ] if rounds else [(0, claim, "") for claim in (result.claims if result else [])]
    entries = []
    for round_number, raw, outcome in returned:
        claim = anchor_claim(raw, shown)
        errors = claim_errors(claim, evidence)
        entries.append({
            **claim.model_dump(mode="json"), "round": round_number, "errors": errors,
            "anchored": claim != raw,
            "outcome": outcome or ("rejected" if errors else "accepted"),
        })
    return {
        "facet": facet, "status": status,
        "rounds": [
            {
                "query": extraction.query, "passage_ids": extraction.passage_ids,
                "gaps": extraction.gaps, "rewrite": extraction.rewrite,
                "scope_hashes": extraction.scope_hashes, "strict": extraction.strict,
                "candidate_ids": extraction.candidate_ids,
            } for extraction in rounds
        ],
        "claims": entries,
    }


async def reconcile(
    state: ResearchState, runtime: Runtime[ResearchContext],
) -> dict[str, object]:
    found = conflicts(state["claims"])
    results: list[Calculation] = []
    claims = list(state["claims"])
    gaps = list(state["coverage"].gaps)

    def add_calculation(request: CalculationRequest) -> None:
        try:
            result = calculate(request, claims)
            first_input = claims[request.input_claims[0]]
            claims.append(Claim(
                text=f"Calculated {result.operation}: {result.value} {result.unit}",
                evidence_ids=result.evidence_ids, quote=first_input.quote,
                subject=first_input.subject, quantity=result.operation,
                value=result.value, unit=result.unit, date=first_input.date,
                conditions=first_input.conditions, scope=first_input.scope,
                calculation_index=len(results),
            ))
            results.append(result)
        except ValueError as error:
            logger.info("calculation_rejected reason=%s", error)
            gaps.append(str(error))

    for index, claim in enumerate(state["claims"]):
        if claim.unit == "kWh/sht":
            add_calculation(CalculationRequest(
                operation="convert", input_claims=[index], target_unit="kWh/t",
            ))
    if state["plan"].intent == "calculation" and state["claims"]:
        request = await runtime.context.models.calculation(
            state["question"], state["claims"], runtime.context.budget,
        )
        previous = len(results)
        add_calculation(request)
        if (
            request.operation == "serial_recovery" and len(results) > previous
            and request.comparison_claim is not None
        ):
            comparison = request.comparison_claim
            if 0 <= comparison < len(state["claims"]) and comparison not in request.input_claims:
                add_calculation(CalculationRequest(
                    operation="percentage_point_difference",
                    input_claims=[comparison, len(claims) - 1], target_unit=None,
                ))
            else:
                gaps.append("Recovery comparison requires a distinct cited observed input claim.")
    return {
        "conflicts": found, "calculations": results, "claims": claims,
        "coverage": state["coverage"].model_copy(update={"gaps": gaps}),
    }

